define(['core/ajax'],function(Ajax){'use strict';var SAVE_INTERVAL_MS=30000;function init(videoId,cmId,occurrenceId,threshold,hasCredit,initialRanges,resumePosition){var video=document.getElementById(videoId);if(!video){return;}if(resumePosition&&resumePosition>5){var resume=function(){if(video.duration&&resumePosition<video.duration-5){video.currentTime=resumePosition;}};if(video.readyState>=1){resume();}else{video.addEventListener('loadedmetadata',resume);}}if(hasCredit){return;}var granted=false;var saving=false;var thresholdSaved=false;var watchedSecs={};var watchedCount=0;var lastSavedCount=0;var lastTime=null;function markRange(from,to){for(var s=Math.floor(from);s<=Math.floor(to);s++){if(!watchedSecs[s]){watchedSecs[s]=true;watchedCount++;}}}if(initialRanges&&initialRanges.length){for(var i=0;i<initialRanges.length;i++){markRange(initialRanges[i][0],initialRanges[i][1]-1);}}lastSavedCount=watchedCount;function buildRanges(){var secs=Object.keys(watchedSecs).map(Number).sort(function(a,b){return a-b;});var ranges=[];var start=null;var prev=null;for(var i=0;i<secs.length;i++){if(start===null){start=secs[i];}else if(secs[i]>prev+1){ranges.push([start,prev+1]);start=secs[i];}prev=secs[i];}if(start!==null){ranges.push([start,prev+1]);}return ranges;}function updateProgressText(pct){var el=document.getElementById('msteamsecp-progress-'+occurrenceId);if(el){el.textContent=M.util.get_string('recording_progress','mod_msteamsecp',pct);}}function onGranted(){granted=true;clearInterval(timer);var indicator=document.getElementById('msteamsecp-completion-indicator-'+occurrenceId);if(indicator){indicator.textContent=M.util.get_string('recording_completion_granted','mod_msteamsecp');indicator.className='alert alert-success mt-2';indicator.style.display='block';}}function save(){if(granted||saving||watchedCount===lastSavedCount){return;}saving=true;var countAtSave=watchedCount;Ajax.call([{methodname:'mod_msteamsecp_save_watch_progress',args:{cmid:cmId,occurrenceid:occurrenceId,ranges:JSON.stringify(buildRanges()),duration:video.duration||0,position:video.currentTime||0},done:function(response){saving=false;lastSavedCount=countAtSave;updateProgressText(response.pct);if(response.credit_granted){onGranted();}},fail:function(){saving=false;thresholdSaved=false;}}]);}video.addEventListener('seeking',function(){lastTime=null;});video.addEventListener('timeupdate',function(){if(granted||!video.duration||video.seeking){return;}var t=video.currentTime;if(lastTime!==null&&t>lastTime&&t-lastTime<2){markRange(lastTime,t);}lastTime=t;var pct=(watchedCount/Math.ceil(video.duration))*100;if(!thresholdSaved&&pct>=threshold){thresholdSaved=true;save();}});video.addEventListener('pause',save);video.addEventListener('ended',save);document.addEventListener('visibilitychange',function(){if(document.visibilityState==='hidden'){save();}});var timer=setInterval(function(){if(!video.paused){save();}},SAVE_INTERVAL_MS);}
return{init:init};});
